package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import io.tenvyr.control.engine.ExecutionService;
import io.tenvyr.control.authority.ExecutionCapsuleService;
import java.time.Instant;
import java.util.*;

/** Operator identity, semantic idempotency and mutation evidence share a transaction. */
public final class WorkbenchCommandService {
    @FunctionalInterface interface Command {ObjectNode execute(Db tx)throws Exception;}
    private final Db db;private final ExecutionService executions;private final RuntimeCoordinationService coordination;private final ExecutionCapsuleService capsules;private final RuntimeConnectionService connections;private final WorkspaceService workspaces;private final WorkspaceExecutionService leases;private final HandoffService handoffs;private final ModelSourceService sources;private final ProviderDiscoveryService providers;private final RuntimeOnboardingService onboarding;private final Map<String,String> environment;
    public WorkbenchCommandService(Db db,ExecutionService executions,RuntimeCoordinationService coordination,ExecutionCapsuleService capsules,RuntimeConnectionService connections,WorkspaceService workspaces,WorkspaceExecutionService leases,HandoffService handoffs,ModelSourceService sources,ProviderDiscoveryService providers,RuntimeOnboardingService onboarding){this(db,executions,coordination,capsules,connections,workspaces,leases,handoffs,sources,providers,onboarding,System.getenv());}
    public WorkbenchCommandService(Db db,ExecutionService executions,RuntimeCoordinationService coordination,ExecutionCapsuleService capsules,RuntimeConnectionService connections,WorkspaceService workspaces,WorkspaceExecutionService leases,HandoffService handoffs,ModelSourceService sources,ProviderDiscoveryService providers,RuntimeOnboardingService onboarding,Map<String,String> environment){this.db=db;this.executions=executions;this.coordination=coordination;this.capsules=capsules;this.connections=connections;this.workspaces=workspaces;this.leases=leases;this.handoffs=handoffs;this.sources=sources;this.providers=providers;this.onboarding=onboarding;this.environment=Map.copyOf(environment);}
    public static String boundedKey(String key){if(key==null||!key.matches("[A-Za-z0-9_.:-]{1,128}"))throw new RuntimeFailure("INVALID_IDEMPOTENCY_KEY","Invalid idempotency key");return key;}
    public static void assertSameRequestPayload(JsonNode stored,JsonNode requested){if(stored!=null&&!stored.isNull()&&!Json.hash(stored).equals(Json.hash(requested)))throw new RuntimeFailure("IDEMPOTENCY_CONFLICT","Idempotency key already owns a different request");}
    private ObjectNode command(String action,JsonNode input,String target,ObjectNode payload,Command execute){String key=boundedKey(Json.text(input,"idempotencyKey"));if(Json.bytes(payload)>16384)throw new RuntimeFailure("PAYLOAD_TOO_LARGE","Command payload exceeds 16384 bytes");return db.transaction(tx->{ObjectNode inserted=tx.one("INSERT INTO operator_actions (action,\"idempotencyKey\",actor,\"targetId\",payload,outcome) VALUES (?,?,?,?,?,?) ON CONFLICT (action,\"idempotencyKey\") DO NOTHING RETURNING *",action,key,"local-operator",target,payload,Json.object("pending",true));ObjectNode row=inserted!=null?inserted:tx.one("SELECT * FROM operator_actions WHERE action=? AND \"idempotencyKey\"=?",action,key);if(row==null)throw new IllegalStateException("Operator action disappeared");assertSameRequestPayload(row.get("payload"),payload);if(inserted==null)return receipt(action,key,"duplicate",row.path("outcome"));ObjectNode result=execute.execute(tx);tx.update("operator_actions",Json.text(row,"id"),Json.object("outcome",result));return receipt(action,key,"executed",result);});}
    static ObjectNode receipt(String action,String key,String outcome,JsonNode result){return Json.object("action",action,"idempotencyKey",key,"outcome",outcome,"result",result);}
    public ObjectNode startTeamRun(JsonNode input){boundedKey(Json.text(input,"idempotencyKey"));String name=HandoffService.truncate(Json.text(input,"name","team-run"),255),goal=input.path("goal").isTextual()?input.path("goal").asText():Json.stringify(input.has("goal")?input.get("goal"):Json.object());if(goal.length()>4096)throw new RuntimeFailure("GOAL_TOO_LARGE","Goal exceeds 4096 characters");ObjectNode config=Coordination.parseConfig(input.path("config"));JsonNode evidence=parseAcceptanceEvidence(input.get("acceptanceEvidence"));String isolation=Json.text(input,"executionIsolation","shared");if(!Set.of("shared","git-worktree").contains(isolation))throw new RuntimeFailure("ALLOCATION_CONFLICT","Unknown workspace isolation");assertExplicitTargetsReady(config);ObjectNode workspace=null;if(input.hasNonNull("workspace")){JsonNode selection=input.get("workspace");if(selection.has("workspaceId"))workspace=workspaces.refreshWorkspace(Json.text(selection,"workspaceId"));else workspace=(ObjectNode)workspaces.createWorkspace(Json.object("name",name,"path",selection.get("path"))).path("snapshot");}if(workspace!=null&&isolation.equals("git-worktree")&&Json.bool(workspace,"dirty",false))throw new RuntimeFailure("DIRTY_SOURCE_NOT_SUPPORTED","Git isolation requires a clean source repository");ObjectNode allocation=workspace==null?null:leases.allocateExecutionWorkspace(workspace,isolation,Json.text(input,"idempotencyKey"));ObjectNode payload=Json.object("name",name,"goalHash",Json.sha256(goal),"config",config,"workspace",workspace==null?null:workspaceIdentity(workspace),"acceptanceEvidence",evidence);if(workspace!=null)payload.put("executionIsolation",isolation);final ObjectNode frozen=workspace;return command("start-team-run",input,null,payload,tx->{ObjectNode pipeline=tx.insert("pipelines",Json.object("name",name.isEmpty()?"team-run":name,"version","1.0","steps",Json.array()));ObjectNode execution=executions.materializeExecutionWithManager(tx.connection(),pipeline,Json.object("goal",goal),null);ObjectNode run=coordination.startRun(tx,Json.text(execution,"id"),config,Instant.now().plusMillis(Json.longValue(config,"loopDeadlineMs",0)),frozen,evidence);ObjectNode lease=allocation==null?null:leases.bindExecutionWorkspace(tx,Json.text(allocation,"id"),Json.text(run,"id"));ObjectNode iteration=coordination.createNextIteration(tx,Json.text(run,"id"));ObjectNode result=Json.object("executionId",execution.get("id"),"runId",run.get("id"),"iterationNumber",iteration.get("iterationNumber"));if(frozen!=null)result.set("workspace",frozen.get("path"));if(lease!=null)result.set("executionWorkspace",Json.object("workspaceExecutionId",lease.get("id"),"mode",lease.get("mode"),"path",lease.get("executionPath"),"baseHeadSha",lease.get("baseHeadSha")));return result;});}
    private static ObjectNode workspaceIdentity(JsonNode workspace){return Json.object("workspaceId",workspace.get("workspaceId"),"path",workspace.get("path"),"repoRoot",workspace.get("repoRoot"),"branch",workspace.get("branch"),"headSha",workspace.get("headSha"),"dirty",workspace.get("dirty"));}
    public static JsonNode parseAcceptanceEvidence(JsonNode input){if(input==null||input.isNull())return Json.value(null);ObjectNode source=RuntimeConnectionService.object(input,"acceptanceEvidence",Set.of("testCommand","buildCommand","lintCommand","typecheckCommand","requiredArtifacts")),out=Json.object();for(String key:List.of("testCommand","buildCommand","lintCommand","typecheckCommand"))if(source.hasNonNull(key)){JsonNode value=source.get(key);if(!value.isTextual()||value.asText().isEmpty()||value.asText().length()>1024)throw new RuntimeFailure("ACCEPTANCE_EVIDENCE_INVALID","Acceptance command exceeds bound");out.set(key,value);}if(source.hasNonNull("requiredArtifacts")){JsonNode artifacts=source.get("requiredArtifacts");if(!artifacts.isArray()||artifacts.size()>16)throw new RuntimeFailure("ACCEPTANCE_EVIDENCE_INVALID","Acceptance artifact list exceeds bound");ArrayNode list=Json.array();for(JsonNode item:artifacts){if(!item.isTextual())throw new RuntimeFailure("ACCEPTANCE_EVIDENCE_INVALID","Acceptance artifact must be text");list.add(HandoffService.truncate(item.asText(),255));}out.set("requiredArtifacts",list);}return out.isEmpty()?Json.value(null):out;}
    public ObjectNode resolveWait(JsonNode input){String id=Json.text(input,"runId");if(!input.path("approve").isBoolean())throw new RuntimeFailure("PAYLOAD_INVALID","Approve must be boolean");return command("resolve-wait",input,id,Json.object("runId",id,"approve",input.get("approve")),tx->Json.object("runId",id,"phase",coordination.resolveWait(tx,id,input.path("approve").asBoolean())));}
    public ObjectNode cancelExecution(JsonNode input){String id=Json.text(input,"executionId");return command("cancel-execution",input,id,Json.object("executionId",id),tx->{ObjectNode e=executions.cancelExecutionWithManager(tx.connection(),id,"Execution cancelled by request");ObjectNode run=tx.one("SELECT * FROM coordination_runs WHERE \"executionId\"=? FOR UPDATE",id);if(run!=null&&!Coordination.TERMINAL.contains(Json.text(run,"phase"))){tx.update("coordination_runs",Json.text(run,"id"),Json.object("phase","CANCELLED","updatedAt",Instant.now().toString()));leases.preserveExecutionWorkspaceForRun(tx,Json.text(run,"id"));}return Json.object("executionId",id,"status",e.get("status"));});}
    public ObjectNode replayExecution(JsonNode input){String id=Json.text(input,"executionId");return command("replay-execution",input,id,Json.object("executionId",id),tx->{ObjectNode r=capsules.replayWithManager(tx.connection(),id,null,"operator",null);ObjectNode run=tx.one("SELECT * FROM coordination_runs WHERE \"executionId\"=?",r.get("targetExecutionId"));if(run!=null&&Json.integer(run,"currentIterationNumber",0)==0)coordination.createNextIteration(tx,Json.text(run,"id"));return Json.object("sourceExecutionId",id,"targetExecutionId",r.get("targetExecutionId"));});}
    public ObjectNode continueRun(JsonNode input){String id=Json.text(input,"sourceExecutionId");ObjectNode config=Coordination.parseConfig(input.get("config")),bundle=handoffs.buildHandoffBundle(id);assertExplicitTargetsReady(config);return command("continue-run",input,id,Json.object("sourceExecutionId",id,"config",config,"bundleHash",Json.hash(bundle)),tx->{ObjectNode result=handoffs.continueRun(tx,id,config,bundle);result.put("sourceExecutionId",id);return result;});}
    public ObjectNode compareExecutions(JsonNode input){String a=Json.text(input,"executionA"),b=Json.text(input,"executionB");return command("compare-executions",input,null,Json.object("executionA",a,"executionB",b),tx->Json.object("comparison",ExecutionCapsuleService.compareCapsules(capsules.buildWithManager(tx.connection(),a),capsules.buildWithManager(tx.connection(),b))));}
    public ObjectNode createConnection(JsonNode input){String id=Json.text(input,"connectionId");ObjectNode profile=RuntimeConnectionService.parseConnectionProfile(input.get("profile"));return command("create-connection",input,id,Json.object("connectionId",id,"profile",profile),tx->{ObjectNode r=connections.createConnection(tx,id,profile);return Json.object("connectionId",id,"revisionNumber",r.get("revisionNumber"));});}
    public ObjectNode reviseConnection(JsonNode input){String id=Json.text(input,"connectionId");ObjectNode profile=RuntimeConnectionService.parseConnectionProfile(input.get("profile"));return command("revise-connection",input,id,Json.object("connectionId",id,"profile",profile),tx->{ObjectNode r=connections.reviseConnection(tx,id,profile);return Json.object("connectionId",id,"revisionNumber",r.get("revisionNumber"));});}
    public ObjectNode revokeConnection(JsonNode input){String id=Json.text(input,"connectionId");return command("revoke-connection",input,id,Json.object("connectionId",id),tx->Json.object("connectionId",id,"status",connections.revokeConnection(tx,id)));}
    public ObjectNode testConnection(JsonNode input){String id=Json.text(input,"connectionId");return command("test-connection",input,id,Json.object("connectionId",id),tx->{ObjectNode probe=connections.testConnection(id,environment);probe.remove("connectionId");return Json.object("connectionId",id,"receipt",probe);});}
    public ObjectNode onboardRuntime(JsonNode input){String kind=Json.text(input,"runtimeKind");ObjectNode status=onboarding.status(kind);if(!Json.bool(status,"detected",false))throw new RuntimeFailure("RUNTIME_NOT_DETECTED","Official runtime executable was not detected");String id=Json.text(input,"connectionId",null);if(id==null){id="conn:"+kind;ObjectNode existing=db.one("SELECT \"statusState\" FROM runtime_connections WHERE \"connectionId\"=?",id);if(existing!=null&&Json.text(existing,"statusState").equals("REVOKED")){Set<String> taken=new HashSet<>();db.query("SELECT \"connectionId\" FROM runtime_connections").forEach(n->taken.add(Json.text(n,"connectionId")));id=allocateReconnectConnectionId(taken,kind);}}ObjectNode profile=RuntimeProfiles.buildRuntimeConnectionProfile(Json.object("runtimeKind",kind,"name",Json.text(input,"name","runtime:"+kind),"executorId","local-host","executable",status.get("executable"),"version",status.hasNonNull("version")?status.get("version"):RuntimeProfiles.template(kind).get("pinnedVersion")));ObjectNode create=createConnection(Json.object("idempotencyKey",Json.text(input,"idempotencyKey")+":create","connectionId",id,"profile",profile)),test=testConnection(Json.object("idempotencyKey",Json.text(input,"idempotencyKey")+":test","connectionId",id));return receipt("onboard-runtime",Json.text(input,"idempotencyKey"),Json.text(create,"outcome"),Json.object("connectionId",id,"runtimeKind",kind,"detected",true,"version",status.get("version"),"authReady",status.get("authReady"),"guidance",status.get("guidance"),"create",create.get("result"),"test",test.get("result")));}
    public static String allocateReconnectConnectionId(Set<String> taken,String kind){for(int n=2;n<100;n++){String id="conn:"+kind+":"+n;if(!taken.contains(id))return id;}for(int n=0;n<8;n++){String id="conn:"+kind+":"+UUID.randomUUID().toString().replace("-","").substring(0,6);if(!taken.contains(id))return id;}throw new RuntimeFailure("CONNECTION_ALREADY_EXISTS","Reconnect identity allocation exhausted");}
    public ObjectNode createWorkspace(JsonNode input){return command("create-workspace",input,null,Json.object("name",input.get("name"),"path",input.get("path")),tx->{ObjectNode created=workspaces.createWorkspace(tx,input);return Json.object("workspaceId",created.get("id"),"snapshot",created.get("snapshot"));});}
    public ArrayNode teamTemplates(){return TeamTemplates.list();}
    public ObjectNode releaseExecutionWorkspace(JsonNode input){return new WorkbenchReleaseWorkspace(db,leases).release(input);}
    public ObjectNode createModelSource(JsonNode input){return command("model-source-create",input,null,Json.object("source",input.get("source")),tx->Json.object("source",sources.create(tx,input.get("source"))));}
    public ObjectNode updateModelSource(JsonNode input){String id=Json.text(input,"sourceId");return command("model-source-update",input,id,Json.object("sourceId",id,"patch",input.get("patch")),tx->Json.object("source",sources.update(tx,id,input.get("patch"))));}
    public ObjectNode deleteModelSource(JsonNode input){String id=Json.text(input,"sourceId");return command("model-source-delete",input,id,Json.object("sourceId",id),tx->{sources.delete(tx,id);return Json.object("sourceId",id,"deleted",true);});}
    public ObjectNode testModelSource(JsonNode input){String id=Json.text(input,"sourceId");return command("model-source-test",input,id,Json.object("sourceId",id),tx->Json.object("source",sources.test(tx,id)));}
    public ObjectNode refreshModelSource(JsonNode input){String id=Json.text(input,"sourceId");return command("model-source-refresh",input,id,Json.object("sourceId",id),tx->sources.refresh(tx,id));}
    public ObjectNode testRuntimeTarget(JsonNode input){String id=Json.text(input,"connectionId"),model=Json.text(input,"modelId");return command("test-runtime-target",input,id,Json.object("connectionId",id,"modelId",model),tx->Json.object("evidence",providers.testRuntimeTarget(id,model)));}
    public ObjectNode openCodeOauthBegin(JsonNode input){ObjectNode payload=Json.object("connectionId",input.get("connectionId"),"providerId",input.get("providerId"),"methodIndex",input.get("methodIndex"));for(String key:List.of("expectedMethodType","expectedMethodLabel"))if(input.has(key))payload.set(key,input.get(key));return command("opencode-oauth-begin",input,Json.text(input,"connectionId"),payload,tx->providers.beginAuthFlow(input));}
    public ObjectNode openCodeOauthComplete(JsonNode input){String id=Json.text(input,"authFlowId");ObjectNode payload=Json.object("authFlowId",id);if(input.has("code"))payload.put("hasCode",true);return command("opencode-oauth-complete",input,id,payload,tx->providers.completeAuthFlow(id,Json.text(input,"code",null)));}
    public ObjectNode auditTrail(String action,int limit){int take=Math.min(100,Math.max(1,limit));List<ObjectNode> rows=action==null?db.query("SELECT id,action,\"idempotencyKey\",actor,\"targetId\",outcome,\"createdAt\" FROM operator_actions ORDER BY \"createdAt\" DESC LIMIT ?",take+1):db.query("SELECT id,action,\"idempotencyKey\",actor,\"targetId\",outcome,\"createdAt\" FROM operator_actions WHERE action=? ORDER BY \"createdAt\" DESC LIMIT ?",action,take+1);return Json.object("items",rows.subList(0,Math.min(take,rows.size())),"truncated",rows.size()>take);}
    private void assertExplicitTargetsReady(JsonNode config){Map<String,List<String>> targets=new HashMap<>();for(String key:List.of("plannerTarget","verifierTarget")){JsonNode t=config.path(key);if(t.has("modelId"))targets.computeIfAbsent(Json.text(t,"connectionId"),k->new ArrayList<>()).add(Json.text(t,"modelId"));}for(JsonNode t:config.path("allowedTargets"))if(t.has("modelId"))targets.computeIfAbsent(Json.text(t,"connectionId"),k->new ArrayList<>()).add(Json.text(t,"modelId"));for(var e:targets.entrySet()){ObjectNode state=providers.discoverRuntimeProviders(e.getKey());if(!Json.text(state,"runtimeKind").equals("opencode"))continue;Set<String> authenticated=new HashSet<>();for(JsonNode p:state.path("providers"))if(Json.bool(p,"authenticated",false))authenticated.add(Json.text(p,"providerId"));for(String model:e.getValue()){int slash=model.indexOf('/');if(slash<1||!authenticated.contains(model.substring(0,slash)))throw new RuntimeFailure("PROVIDER_NOT_AUTHENTICATED","Explicit OpenCode target requires an authenticated provider");}}}
}
